// src/utils/claudeApi.js

const PROXY = "/api/claude";

export async function callClaude({ system, userMessage, tools = [], maxTokens = 4000 }) {
  const body = {
    model:      "claude-sonnet-4-6",   // ✅ correct model string
    max_tokens: maxTokens,
    system,
    messages: [{ role: "user", content: userMessage }],
  };
  if (tools.length > 0) body.tools = tools;

  const res = await fetch(PROXY, {
    method:  "POST",
    headers: { "Content-Type": "application/json" },
    body:    JSON.stringify(body),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    // Show real error from Anthropic, not generic message
    const msg = err?.error?.message || JSON.stringify(err) || `HTTP ${res.status}`;
    throw new Error(msg);
  }
  return res.json();
}

export function extractText(data) {
  return (data?.content || [])
    .filter(b => b.type === "text")
    .map(b => b.text)
    .join("");
}

export const WEB_SEARCH_TOOL = [
  { type: "web_search_20250305", name: "web_search" },
];
